import ast, glob, re, sys

def doc(f):
    return ast.get_docstring(ast.parse(open(f, encoding='utf-8').read())) or ''

clis = [f for f in sorted(glob.glob('_tools/*.py')) if "__name__ == '__main__'" in open(f, encoding='utf-8').read().replace('"', "'")]
KEY = re.compile(r'\s*(Answers|Use|MCP):')

def bad(f):
    lines = doc(f).splitlines()
    first = next((i for i, l in enumerate(lines) if l.strip().startswith('Answers:')), None)
    if first is None:
        return 'no Answers: line'
    tail = lines[first:]
    if not any(l.strip().startswith('Use:') for l in tail):
        return 'no Use: line at the end'
    prose = [l for l in tail if l.strip() and not KEY.match(l) and not l[:1].isspace()]
    return f'prose after the first Answers: line: {prose[0][:40]!r}' if prose else ''

problems = {f: bad(f) for f in clis}
problems = {f: p for f, p in problems.items() if p}

# a kb MCP tool runs these scripts (kb_mcp.py's facade, coord and settings calls): their docstrings name the tool
src = open('_tools/kb_mcp.py', encoding='utf-8').read()
tools = set(re.findall(r'"name": "((?:kb|docs|coord)_\w+)"', src))
runs = ['backlog.py', 'check.py', 'coord.py', 'kbmon.py', 'kbsettings.py', 'querylog.py', 'rag.py', 'selfdoc.py']
for name in runs:
    f = f'_tools/{name}'
    mcp = [l.strip()[4:] for l in doc(f).splitlines() if l.strip().startswith('MCP:')]
    if not any(t in line for line in mcp for t in tools):
        problems[f] = problems.get(f, '') + ' no MCP: line naming a kb MCP tool'
for f, p in sorted(problems.items()):
    print(f, '-', p.strip())
print('command-line tools', len(clis), '| without the trailing Answers:/Use: lines or the MCP: line', len(problems))
sys.exit(1 if problems else 0)

import json, subprocess, sys

def run(*args):
    return subprocess.run([sys.executable, '_tools/kbtools.py', *args], capture_output=True, text=True)

def top(need, n):
    r = run(need, '--json')
    try:
        return [e.get('tool') for e in json.loads(r.stdout)['entries']][:n]
    except (ValueError, KeyError, TypeError):
        return []

cli = {'what a sprint item cost in tokens and dollars': 'backlog.py',
       'which sessions are running and what is stalled': 'kbmon.py',
       'which docs describe a file I am changing': 'selfdoc.py'}
other = {'plan and run a sprint of the backlog': 'kb-sprint',
         'read the backlog without writing to it': 'kb_backlog',
         'review a workspace against the kb facts': 'kb-reviewer'}
got = {need: top(need, 3) for need in cli}
got.update({need: top(need, 5) for need in other})
ok = all(want in got[need] for need, want in {**cli, **other}.items())
need = next(iter(cli))
a, b = run(need, '--json'), run(need, '--json')
same = a.returncode == 0 and a.stdout == b.stdout and run(need).stdout == run(need).stdout
few = 0 < len(json.loads(a.stdout)['entries']) <= 10 if a.stdout.strip().startswith('{') else False
plain = run(need)
shows = plain.returncode == 0 and 'backlog.py' in plain.stdout
nothing = run('zqxv wlkj nmbp qrtz', '--json')
try:
    empty = json.loads(nothing.stdout)['entries'] == []
except (ValueError, KeyError, TypeError):
    empty = False
print('top entries', got, '| deterministic', same, '| a few entries', few, '| plain text names the tool', shows, '| nonsense matches nothing', empty)
sys.exit(0 if ok and same and few and shows and empty else 1)
